const now = new Date();
const hour = now.getHours();

let promptText = "";
let icon = "";

// Check if it's the morning run (before noon)
if (hour < 12) {
    icon = "*Daily DSA Knowledge*";
    promptText = "You are a Senior Software Engineer. Explain one specific, advanced concept related to Data Structures, Algorithms, or System Design. Include a brief 'Why it matters' section. Keep it under 100 words.";
} else {
    // Evening run (10 PM)
    icon = "*Nightly Joke*";
    promptText = "Tell me a random, witty, and intelligent joke related to programming or tech. Keep it short.";
}

return {
    prompt: promptText,
    header: icon
};

// Get the output from the HTTP Request
const response = $input.first().json;
let aiText = "";

// 1. Try to find the text in standard Gemini location
if (response.candidates && response.candidates[0]?.content?.parts?.[0]?.text) {
    aiText = response.candidates[0].content.parts[0].text;
} 
// 2. Try to find it in the structure you are seeing (content -> parts)
else if (response.content && response.content.parts?.[0]?.text) {
    aiText = response.content.parts[0].text;
} 
else {
    aiText = "Could not parse AI response. Check input.";
}

// 3. Fix "JSON String" issue
// Sometimes AI returns a JSON string (like '{"contents": ...}') instead of just the text.
// We parse it to get the actual message inside.
try {
    const trimmed = aiText.trim();
    if (trimmed.startsWith('{') && trimmed.includes('"parts"')) {
        const parsed = JSON.parse(trimmed);
        if (parsed.contents && parsed.contents[0].parts[0].text) {
            aiText = parsed.contents[0].parts[0].text;
        }
    }
} catch (e) {
    // If parsing fails, it was probably just regular text that started with {
}

return {
    json: {
        cleanedMessage: aiText,
        originalHeader: $('Code').first().json.header // Pass the header through
    }
};
